288	    private <T> T findEntityById(Supplier<T> supplier) {
289	        try {
290	            return supplier.get();
291	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
292	            // Just ignore not found exceptions for Jdbc/Jpa realization
