16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    public String getHouseholdId() {
118	        return this.householdId;
119	    }
120	
121	    public void setHouseholdId(String householdId) {
122	        this.householdId = householdId;
123	    }
124	
125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
135	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
136	     * from the owner's own fields; absent until both the customer code and registration date
137	     * have been assigned.
138	     */
139	    public String getMembershipNumber() {
140	        if (this.customerCode == null || this.registrationDate == null) {
141	            return null;
142	        }
143	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
144	    }
145	
146	    /**
147	     * The owner's membership tier: {@code "SILVER"} when this owner has no namesakes
148	     * ({@code namesakeCount} is 0) and an email address is present, otherwise
149	     * {@code "BRONZE"}. Derived from the owner's own fields.
150	     */
151	    public String getMembershipTier() {
152	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
153	        boolean hasEmail = this.email != null && !this.email.isEmpty();
154	        return unique && hasEmail ? "SILVER" : "BRONZE";
155	    }
156	
157	    /**
158	     * Fixed city-to-region lookup backing {@link #getLocality()}. Cities absent from this
159	     * table derive the locality {@code "UNKNOWN"}.
160	     */
161	    private static final Map<String, String> CITY_REGIONS =
162	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
163	
164	    /**
165	     * The owner's locality: the canonical region derived from {@link #getCity() city} using the
166	     * fixed {@link #CITY_REGIONS} table, or {@code "UNKNOWN"} when the city is not in the table.
167	     */
168	    public String getLocality() {
169	        return CITY_REGIONS.getOrDefault(this.city, "UNKNOWN");
170	    }
171	
172	    /**
173	     * Default the registration date to the server's current date when none was
174	     * supplied, so a newly registered owner always has a registration date.
175	     */
176	    @PrePersist
177	    private void defaultRegistrationDate() {
178	        if (this.registrationDate == null) {
179	            this.registrationDate = LocalDate.now();
180	        }
181	    }
182	
183	    protected Set<Pet> getPetsInternal() {
184	        if (this.pets == null) {
185	            this.pets = new HashSet<>();
186	        }
187	        return this.pets;
188	    }
189	
190	    protected void setPetsInternal(Set<Pet> pets) {
191	        this.pets = pets;
192	    }
193	
194	    public List<Pet> getPets() {
195	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
196	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
197	        return Collections.unmodifiableList(sortedPets);
198	    }
199	
200	    public void setPets(List<Pet> pets) {
201	        this.pets = new HashSet<>(pets);
202	    }
