63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final OwnerRequestValidator ownerRequestValidator;
75	
76	    private final HouseholdDuplicateValidator householdDuplicateValidator;
77	
78	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
79	
80	    private final DailyOwnerLimitValidator dailyOwnerLimitValidator;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final EmailNormalizer emailNormalizer;
85	
86	    private final AddressNormalizer addressNormalizer;
87	
88	    private final CustomerCodeGenerator customerCodeGenerator;
89	
90	    private final HouseholdRegistrar householdRegistrar;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 OwnerRequestValidator ownerRequestValidator,
97	                                 HouseholdDuplicateValidator householdDuplicateValidator,
98	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
99	                                 DailyOwnerLimitValidator dailyOwnerLimitValidator,
100	                                 TelephoneNormalizer telephoneNormalizer,
101	                                 EmailNormalizer emailNormalizer,
102	                                 AddressNormalizer addressNormalizer,
103	                                 CustomerCodeGenerator customerCodeGenerator,
104	                                 HouseholdRegistrar householdRegistrar) {
105	        this.clinicService = clinicService;
106	        this.ownerMapper = ownerMapper;
107	        this.petMapper = petMapper;
108	        this.visitMapper = visitMapper;
