150	        this.householdDuplicateValidator.validate(ownerFieldsDto);
151	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
152	        this.dailyOwnerLimitValidator.validate();
153	        String telephone = this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
154	        ownerFieldsDto.setTelephone(telephone);
155	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
156	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
157	            throw new DuplicateTelephoneException(telephone);
158	        }
159	        HttpHeaders headers = new HttpHeaders();
160	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
161	        owner.setCustomerCode(
162	            this.customerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
163	                this.clinicService.countOwnersInCity(owner.getCity())));
164	        owner.setNamesakeCount(
165	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
166	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
167	            this.householdRegistrar.register(owner);
168	        }
169	        this.clinicService.saveOwner(owner);
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
