212	        HttpHeaders headers = new HttpHeaders();
213	        Pet pet = petMapper.toPet(petFieldsDto);
214	        owner.setId(ownerId);
215	        pet.setOwner(owner);
216	        pet.getType().setName(null);
217	        this.clinicService.savePet(pet);
218	        PetDto petDto = petMapper.toPetDto(pet);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
220	            .buildAndExpand(pet.getId()).toUri());
221	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
227	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
228	        if (currentOwner != null) {
229	            Pet currentPet = this.clinicService.findPetById(petId);
230	            if (currentPet != null) {
231	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
232	                currentPet.setName(petFieldsDto.getName());
