17	package org.springframework.samples.petclinic.rest.assignment;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.rest.validation.HouseholdKey;
21	import org.springframework.samples.petclinic.service.ClinicService;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Enrolls an owner into its household when the create deliberately shares one. The joining owner and
26	 * every existing owner at the same last name and address are stamped with the same stable
27	 * {@code householdId}, so a whole household carries one shared identifier.
28	 */
29	@Component
30	public class HouseholdRegistrar {
31	
32	    private final ClinicService clinicService;
33	
34	    private final HouseholdKey householdKey;
35	
36	    private final HouseholdIdGenerator householdIdGenerator;
37	
38	    public HouseholdRegistrar(ClinicService clinicService,
39	                              HouseholdKey householdKey,
40	                              HouseholdIdGenerator householdIdGenerator) {
41	        this.clinicService = clinicService;
42	        this.householdKey = householdKey;
43	        this.householdIdGenerator = householdIdGenerator;
44	    }
45	
46	    /**
47	     * Assign the shared household identifier to {@code owner} and back-fill it onto the existing
48	     * housemates that lack it. The caller is responsible for saving {@code owner} itself.
49	     *
50	     * @param owner the owner being created, not yet saved
51	     * @return the stable household identifier assigned to the owner
52	     */
53	    public String register(Owner owner) {
54	        String householdId = this.householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
55	        owner.setHouseholdId(householdId);
56	        String key = this.householdKey.of(owner.getLastName(), owner.getAddress());
57	        for (Owner housemate : this.clinicService.findAllOwners()) {
58	            if (this.householdKey.of(housemate.getLastName(), housemate.getAddress()).equals(key)
59	                && !householdId.equals(housemate.getHouseholdId())) {
60	                housemate.setHouseholdId(householdId);
61	                this.clinicService.saveOwner(housemate);
62	            }
63	        }
64	        return householdId;
65	    }
66	}
